package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.capacity.*;
import cn.mop.domain.capacity.CapacityScenarioRepository.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.time.Instant;
import java.util.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class CapacityScenarioControllerTest {
    static final String ACTOR="66000000-0000-4000-8000-000000000001",TENANT="66000000-0000-4000-8000-000000000002",ID="66000000-0000-4000-8000-000000000003";
    PlatformRepository platform;CapacityScenarioRepository repository;CapacityScenarioController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);repository=mock(CapacityScenarioRepository.class);controller=new CapacityScenarioController(platform,repository,mapper);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,"padmin",1,true)));}
    MockHttpServletRequest request(String method){var r=new MockHttpServletRequest(method,"/api/v1/capacity/scenarios");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setAttribute("mop.trace_id","capacity-scenario-test");r.addHeader("Idempotency-Key","synthetic-scenario-key");return r;}
    Access access(){return new Access(ACTOR,TENANT,1,"capacity-scenario-test");}
    ObjectNode input(){var v=mapper.createObjectNode().put("expected_version",0).put("label","合成方案").put("note","仅用于合成测试").putNull("benchmark_reference");v.set("calculation",new CapacityEstimateControllerTest().input());return v;}
    CapacityScenarioDraft draft(){var v=input();return new CapacityScenarioDraft(v.get("label").asText(),v.get("note").asText(),CapacityCalculation.fromWire(mapper.convertValue(v.get("calculation"),Object.class)),null);}
    Stored row(){var d=draft();return new Stored(ID,TENANT,ACTOR,Instant.parse("2026-10-03T12:00:00.123Z"),1,d,d.calculation().snapshot(),"a".repeat(64),"b".repeat(64));}
    Map<?,?> data(Object response){return (Map<?,?>)((Map<?,?>)response).get("data");}
    @Test void createUsesCurrentAuthorizationGuardThenImmutableWrite(){when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return ((Supplier<?>)c.getArgument(7)).get();});when(repository.create(access(),0,draft())).thenReturn(row());var result=data(controller.write(input(),request("POST")));assertEquals(ID,result.get("id"));assertEquals(1L,result.get("version"));var order=inOrder(repository);order.verify(repository).authorizeCreate(access());order.verify(repository).create(access(),0,draft());}
    @Test void savedDtoNeverClaimsEffectiveMeasuredApprovedOrPoc(){var d=CapacityScenarioController.dto(row());assertEquals("DRAFT",d.get("lifecycle_status"));assertEquals("UNVERIFIED",d.get("model_approval_status"));assertEquals("UNVERIFIED",d.get("measurement_verification"));assertEquals("NOT_RUN",d.get("poc_status"));assertEquals(false,d.get("effective"));assertEquals(false,d.get("production_capacity_verified"));assertNull(d.get("measured_capacity"));assertNull(d.get("approved_pool_nvps_limit"));assertEquals("NOT_PROVIDED",d.get("benchmark_verification"));assertFalse(d.containsKey("scenario_saved"));assertEquals("2026-10-03T12:00:00.123Z",d.get("recorded_at"));var s=(Map<?,?>)d.get("snapshot");assertEquals("100",((Map<?,?>)s.get("outputs")).get("nvps"));assertEquals("50400000",((Map<?,?>)s.get("proxy_buffer")).get("estimated_bytes"));}
    @Test void getIsReadonlyCurrentTenantAndForeignMissingPropagates(){when(repository.get(access(),ID)).thenReturn(row());assertEquals(TENANT,data(controller.get(ID,request("GET"))).get("tenant_id"));verify(platform,never()).idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any());when(repository.get(access(),ID)).thenThrow(new DomainException(404,"OBJECT_NOT_FOUND","missing"));assertEquals(404,assertThrows(DomainException.class,()->controller.get(ID,request("GET"))).status);}
    @Test void cachedReceiptStillRunsFreshGuardAndNeverCreatesAgain(){when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{((Runnable)c.getArgument(6)).run();return Map.of("original",true);});assertEquals(true,data(controller.write(input(),request("POST"))).get("original"));verify(repository).authorizeCreate(access());verify(repository,never()).create(any(),anyLong(),any());}
    @Test void roleAndSessionGatesPrecedeAnyRepositoryCall(){for(String role:List.of("viewer","tadmin","msp","unknown")){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,1,true)));assertEquals(403,assertThrows(DomainException.class,()->controller.write(input(),request("POST"))).status);assertEquals(403,assertThrows(DomainException.class,()->controller.list(request("GET"))).status);}var r=request("GET");r.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.list(r)).status);verifyNoInteractions(repository);}
    @Test void createVersionMustBeZeroAndAllFieldsAreExplicit(){for(JsonNode n:List.of(new IntNode(1),new IntNode(-1),new TextNode("0"),new DoubleNode(0.0),new LongNode(4294967296L))){var v=input();v.set("expected_version",n);assertEquals(400,assertThrows(DomainException.class,()->controller.write(v,request("POST"))).status);}for(String name:List.of("label","note","calculation","benchmark_reference","expected_version")){var v=input();v.remove(name);assertThrows(DomainException.class,()->controller.write(v,request("POST")));}assertThrows(DomainException.class,()->controller.write(input().put("effective",true),request("POST")));}
    @Test void nestedMalformedNumbersReferenceAndRawTextFailBeforeWrites(){for(String field:List.of("label","note")){assertThrows(DomainException.class,()->controller.write(input().put(field," "),request("POST")));}var numeric=input();((ObjectNode)numeric.get("calculation").get("inputs")).put("hosts",10);assertEquals(400,assertThrows(DomainException.class,()->controller.write(numeric,request("POST"))).status);var bad=input();bad.putObject("benchmark_reference").put("reference","https://example.invalid").put("title","ref").put("sha256","a".repeat(64));assertThrows(DomainException.class,()->controller.write(bad,request("POST")));verifyNoInteractions(repository);}
    @Test void idempotencyKeyAndNoWriteQueriesAreRequired(){var r=request("POST");r.removeHeader("Idempotency-Key");assertThrows(DomainException.class,()->controller.write(input(),r));var q=request("POST");q.addParameter("tenant_id",ACTOR);assertThrows(DomainException.class,()->controller.write(input(),q));}
    @Test void nestedFieldOrderingHasStableHashButChangedNoteDoesNot(){List<String> hashes=new ArrayList<>();when(platform.idempotentAuthorized(any(),any(),any(),any(),any(),anyLong(),any(),any())).thenAnswer(c->{hashes.add(c.getArgument(4));return Map.of("ok",true);});controller.write(input(),request("POST"));var reordered=input();var calc=(ObjectNode)reordered.get("calculation");var hosts=((ObjectNode)calc.get("inputs")).remove("hosts");((ObjectNode)calc.get("inputs")).set("hosts",hosts);controller.write(reordered,request("POST"));controller.write(input().put("note","另一个说明"),request("POST"));assertEquals(hashes.get(0),hashes.get(1));assertNotEquals(hashes.get(0),hashes.get(2));}
    @Test void boundedListUsesExtraRowAndPairedStableCursor(){var r=request("GET");r.addParameter("page_size","10");r.addParameter("label_query","%_中文");when(repository.list(access(),"%_中文",11,null,null)).thenReturn(Collections.nCopies(11,row()));var d=data(controller.list(r));assertEquals(10,((List<?>)d.get("items")).size());assertEquals(true,d.get("has_more"));assertEquals(ID,d.get("next_before_id"));assertEquals(row().recordedAt().toString(),d.get("next_before_recorded_at"));var q=request("GET");q.addParameter("before_id",ID);assertThrows(DomainException.class,()->controller.list(q));var unknown=request("GET");unknown.addParameter("note_query","secret");assertThrows(DomainException.class,()->controller.list(unknown));}
    @Test void strictBodyRejectsDuplicateTrailingDeepAndOversized()throws Exception{for(String raw:List.of("{\"label\":1,\"label\":2}","{} {}","[[[[[1]]]]]"," ".repeat(32769))){var r=request("POST");r.setContent(raw.getBytes(java.nio.charset.StandardCharsets.UTF_8));assertThrows(DomainException.class,()->CapacityScenarioController.body(r));}var r=request("POST");r.setContent(mapper.writeValueAsBytes(input()));assertEquals(input(),CapacityScenarioController.body(r));}
}
